-- 001_initial
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1, CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS user_settings(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_currency TEXT NOT NULL DEFAULT 'IDR' CHECK(display_currency IN ('IDR','USD')), language TEXT NOT NULL DEFAULT 'ID' CHECK(language IN ('ID','EN')), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS investment_types(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,name));
CREATE INDEX IF NOT EXISTS investment_types_user ON investment_types(user_id);
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, investment_type_id INTEGER NOT NULL REFERENCES investment_types(id), name TEXT NOT NULL, symbol TEXT, unit TEXT NOT NULL, quantity_scale INTEGER NOT NULL DEFAULT 8 CHECK(quantity_scale BETWEEN 0 AND 12), quote_currency TEXT NOT NULL CHECK(quote_currency IN ('IDR','USD')), pricing_mode TEXT NOT NULL DEFAULT 'manual' CHECK(pricing_mode IN ('manual','automatic','fixed')), provider TEXT, provider_symbol TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,name));
CREATE INDEX IF NOT EXISTS assets_user_type ON assets(user_id,investment_type_id);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, asset_id INTEGER NOT NULL REFERENCES assets(id), kind TEXT NOT NULL CHECK(kind IN ('buy','sell','deposit','withdrawal')), quantity TEXT NOT NULL, unit_price TEXT NOT NULL, quote_currency TEXT NOT NULL CHECK(quote_currency IN ('IDR','USD')), fx_rate_to_idr TEXT NOT NULL, occurred_at TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS transactions_user_date ON transactions(user_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS transactions_asset ON transactions(user_id,asset_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS asset_prices(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, asset_id INTEGER NOT NULL REFERENCES assets(id) ON DELETE CASCADE, price TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency IN ('IDR','USD')), source TEXT NOT NULL, priced_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS asset_prices_latest ON asset_prices(user_id,asset_id,priced_at DESC);
CREATE TABLE IF NOT EXISTS exchange_rates(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, base_currency TEXT NOT NULL, quote_currency TEXT NOT NULL, rate TEXT NOT NULL, source TEXT NOT NULL, priced_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS exchange_rates_latest ON exchange_rates(user_id,base_currency,quote_currency,priced_at DESC);
CREATE TABLE IF NOT EXISTS portfolio_snapshots(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_key TEXT NOT NULL, total_value_idr TEXT NOT NULL, net_invested_idr TEXT NOT NULL, realized_pl_idr TEXT NOT NULL, unrealized_pl_idr TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,refresh_key));
CREATE INDEX IF NOT EXISTS snapshots_user_date ON portfolio_snapshots(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS portfolio_snapshot_items(id INTEGER PRIMARY KEY, snapshot_id INTEGER NOT NULL REFERENCES portfolio_snapshots(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, asset_id INTEGER NOT NULL REFERENCES assets(id), quantity TEXT NOT NULL, average_cost TEXT NOT NULL, price TEXT NOT NULL, quote_currency TEXT NOT NULL, fx_rate_to_idr TEXT NOT NULL, market_value_idr TEXT NOT NULL, cost_basis_idr TEXT NOT NULL, realized_pl_idr TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS snapshot_items_owner ON portfolio_snapshot_items(user_id,snapshot_id);
CREATE TABLE IF NOT EXISTS price_refreshes(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_key TEXT NOT NULL, status TEXT NOT NULL, error_summary TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,refresh_key));
CREATE INDEX IF NOT EXISTS price_refreshes_user ON price_refreshes(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS quote_cache(id INTEGER PRIMARY KEY, provider TEXT NOT NULL, symbol TEXT NOT NULL, price TEXT, currency TEXT, source TEXT NOT NULL DEFAULT '', fetched_at TEXT, error TEXT NOT NULL DEFAULT '', error_at TEXT, failure_count INTEGER NOT NULL DEFAULT 0, backoff_until TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,symbol));
CREATE INDEX IF NOT EXISTS quote_cache_provider_symbol ON quote_cache(provider,symbol);
